/bin/bash -lc "node <<'NODE'
const { execFileSync } = require('node:child_process');
const base58 = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
const safe = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"'!@#$%''^&*()_+-=[]{};:,./?";
function randInt(max) { return Math.floor(Math.random() * max); }
function randFrom(chars, length) { let out = '"''; for (let i = 0; i < length; i += 1) out += chars[randInt(chars.length)]; return out; }
for (let i = 0; i < 20; i += 1) {
  const args = [
    '--a', randFrom(safe, randInt(8)),
    '--b', randFrom(base58, 1 + randInt(16)),
    '--c', randFrom(safe, randInt(10)),
    '--d', randFrom(safe, randInt(12)),
    '--e', randFrom(base58, 1 + randInt(20)),
    '--f', String(randInt(1_000_000_000)),
    '--g', String(randInt(1_000_000_000)),
  ];
  const left = execFileSync('/workspace/dataset/test20_executable', args, { encoding: 'utf8' });
  const right = execFileSync('node', ['/output/test20.mjs', ...args], { encoding: 'utf8' });
  if (left "'!== right) {
    console.error('"'Mismatch on case', i, args);
    console.error('Executable:\\n' + left);
    console.error('Node:\\n' + right);
    process.exit(1);
  }
}
console.log('Randomized comparison passed for 20 cases.');
NODE"

